values
  ('s001', '개화 (Flowering)', 'DEAR.', '싱글', 2020, true, '{"벅참","위로","설렘"}', '{"힘들때","새벽감성"}', 3, '겨우내 움츠렸던 마음이 천천히 피어나는 듯한 데뷔곡. 힘든 시기를 지나는 사람에게 건네는 응원 같은 곡이에요.', NULL, NULL),
  ('s002', '조깅', 'PANORAMA', '미니', 2020, true, '{"신남","설렘","후련"}', '{"운동·러닝","출근길·등굣길"}', 4, '통통 튀는 바이올린과 청량한 사운드가 발걸음을 가볍게 만들어요. 아침 러닝에 딱.', NULL, NULL),
  ('s003', 'Flare', 'PANORAMA', '미니', 2020, false, '{"열정","신남"}', '{"운동·러닝","드라이브"}', 4, '점점 타오르는 전개가 텐션을 끌어올려 줘요.', NULL, NULL),
  ('s004', '수박깨러가', 'PANORAMA', '미니', 2020, false, '{"신남","설렘"}', '{"여행","친구와놀때"}', 4, '여름 바다로 떠나고 싶어지는 상큼한 곡이에요.', NULL, NULL),
  ('s005', 'Missing Call', 'PANORAMA', '미니', 2020, false, '{"그리움","외로움"}', '{"새벽감성","비오는날"}', 3, '닿지 않는 연락처럼 아련한 감정이 번지는 곡. 게스트 보컬이 그리움을 더해요.', NULL, '수란'),
  ('s006', '충분히', 'PANORAMA', '미니', 2020, false, '{"위로","차분"}', '{"힘들때","잠들기전"}', 2, '지금 그대로도 괜찮다고 다독여 주는 잔잔한 위로예요.', NULL, NULL),
  ('s007', '선잠', 'Snooze', '싱글', 2020, true, '{"나른함","차분"}', '{"잠들기전","새벽감성"}', 2, '설핏 든 잠처럼 몽롱하고 포근해서 잠들기 전에 어울려요.', NULL, NULL),
